using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information using the web_search tool.
    2. Taking notes on important findings using the take_note tool.
    3. After gathering enough information, summarize all your notes into a final report.

    Always search multiple aspects of the topic and take organized notes before summarizing.
    """)
{
    Name = "ResearchAgent",
    Tools = [.. AIFunctionFactory.Create(researchTools)],
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

// Display collected notes
var noteService = host.Services.GetRequiredService<NoteService>();
var notes = noteService.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine($"\n📝 Notes collected ({notes.Count}):");
    foreach (var (category, content) in notes)
    {
        Console.WriteLine($"  [{category}] {content}");
    }
}

/// <summary>Stores research notes collected during the agent's investigation.</summary>
public sealed class NoteService
{
    private readonly List<(string Category, string Content)> _notes = [];

    public void AddNote(string category, string content) => _notes.Add((category, content));

    public IReadOnlyList<(string Category, string Content)> GetAllNotes() => _notes;
}

/// <summary>Tools available to the research agent for web searching and note-taking.</summary>
public sealed class ResearchTools(NoteService noteService)
{
    [Description("Search the web for information on a given query. Returns relevant search results.")]
    [AIFunction(Name = "web_search")]
    public Task<string> WebSearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search — replace with a real search API (e.g., Bing Search, Tavily)
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        var results = $"""
            Search results for "{query}":
            1. [Article] Comprehensive overview of {query} - covers key concepts, history, and current developments.
            2. [Research Paper] Recent advances in {query} - peer-reviewed findings from 2025.
            3. [News] Latest updates on {query} - breaking developments and expert analysis.
            Note: These are simulated results. Connect a real search API (Bing, Tavily, SerpAPI) for production use.
            """;

        return Task.FromResult(results);
    }

    [Description("Take a note to remember important information found during research.")]
    [AIFunction(Name = "take_note")]
    public string TakeNote(
        [Description("The category for this note (e.g., 'key_fact', 'statistic', 'definition', 'source')")] string category,
        [Description("The content of the note")] string content)
    {
        noteService.AddNote(category, content);
        Console.WriteLine($"  📝 Note [{category}]: {content[..Math.Min(content.Length, 60)]}...");
        return $"Note saved under '{category}'.";
    }
}

